	FROM [staging_fo].[VENDTABLE] stg
		LEFT JOIN [synapse_fo].[VENDTABLE] tgt
			ON stg.[AccountNum] = tgt.[AccountNum] 
			AND stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
		
	WHERE tgt.[RECID] IS NULL
